<div class="page-heading"><div><div class="breadcrumb-lite">Organization / Location</div><h1><?= e($location['name_en']) ?></h1><p><?= e($location['dad_number']) ?> &middot; <?= e($location['type_name']) ?></p></div><a class="btn btn-outline-secondary" href="<?= e(url('locations/type/'.$location['type_key'])) ?>">Back to List</a></div>
